 const r=al(block,'Links adicionais','HORIZONTAL',320,36,12);
 [['Outras publicações','book'],['Solicitar estudo bíblico','study']].forEach(([label,ic])=>{const a=al(r,label,'HORIZONTAL',154,36,6,C.soft);a.paddingLeft=7;a.paddingRight=7;a.cornerRadius=6;a.counterAxisAlignItems='CENTER';svg(a,ic,19);txt(a,label,11,'Medium',C.primary,110);});
}
function body(f){const b=al(f,'Conteúdo da tela','VERTICAL',320,414,0);b.x=12;b.y=108;return b;}
function spacer(p,h){return al(p,'Espaçamento','VERTICAL',320,h);}
function content(f,downloaded=[],indexes=[0,1,2,3],showLinks=true){const b=body(f);const docs=indexes.filter(i=>i<2),vids=indexes.filter(i=>i>1);
 if(docs.length)rowCards(b,docs,downloaded);
 if(docs.length&&vids.length)spacer(b,12);
 if(vids.length){txt(b,'Vídeos',16,'Bold');spacer(b,8);rowCards(b,vids,downloaded);}
 if(showLinks){spacer(b,12);links(b);}return b;
}
function empty(f,label,kind){const b=al(f,'Estado vazio','VERTICAL',304,190,16);b.x=20;b.y=184;b.counterAxisAlignItems='CENTER';b.primaryAxisAlignItems='CENTER';const badge=al(b,'Ícone do estado','HORIZONTAL',64,64,0,C.soft);badge.cornerRadius=32;badge.counterAxisAlignItems='CENTER';badge.primaryAxisAlignItems='CENTER';svg(badge,kind,28);const t=txt(b,label,16,'Medium',C.ink,284);t.textAlignHorizontal='CENTER';}
const specs=[['01 · Início — estado inicial','home'],['02 · Início — documento e vídeo baixados','mixed'],['03 · Início — quatro itens baixados','all'],['04 · Baixado — conteúdos disponíveis','downloaded'],['05 · Baixado — nenhum conteúdo','empty'],['06 · Busca — campo aberto','search'],['07 · Busca — resultados por título','results'],['08 · Busca — nenhum resultado','none'],['09 · Atualização — carregando','loading'],['10 · Atualização — conteúdo atualizado','updated'],['11 · Outras publicações','publications'],['12 · Solicitar estudo bíblico','study']];
specs.forEach(([name,state],i)=>{const f=track(figma.createFrame());f.name=name;f.resize(344,534);f.fills=paint(C.bg);f.clipsContent=true;f.x=80+(i%4)*392;f.y=80+Math.floor(i/4)*598;page.appendChild(f);screens.push(f);
 const isLink=['publications','study'].includes(state);const isSearch=['search','results','none'].includes(state);const selected=['downloaded','empty'].includes(state)?'Baixado':'Tudo';
 header(f,isLink?'link':isSearch?'search':'home',isLink?(state==='publications'?'Outras publicações':'Solicitar estudo bíblico'):'',state==='results'?'BÍBL':state==='none'?'Esperança':'');
 if(isLink)return;
 tabs(f,selected);
 if(state==='empty'){empty(f,'Nenhum conteúdo baixado','empty');return;}
 if(state==='none'){empty(f,'Nenhum resultado encontrado','search');return;}
 if(state==='downloaded'){content(f,[0,2],[0,2]);return;}
 if(state==='results'){content(f,[],[2,3]);return;}
 const d=state==='all'?[0,1,2,3]:['mixed','loading','updated'].includes(state)?[0,2]:[];
 content(f,d);
 if(state==='loading'){rect(f,0,96,344,3,C.soft);rect(f,0,96,125,3,C.primary);const toast=al(f,'Indicador de carregamento','HORIZONTAL',184,38,10,C.ink);toast.x=80;toast.y=480;toast.cornerRadius=8;toast.counterAxisAlignItems='CENTER';toast.primaryAxisAlignItems='CENTER';svg(toast,'refresh',17,C.white);txt(toast,'Atualizando conteúdo',12,'Medium',C.white);}
 if(state==='updated'){const toast=al(f,'Confirmação de atualização','HORIZONTAL',216,38,8,C.ink);toast.x=64;toast.y=480;toast.cornerRadius=8;toast.counterAxisAlignItems='CENTER';toast.primaryAxisAlignItems='CENTER';svg(toast,'check',18,'#BDE6D2');txt(toast,'Conteúdo atualizado',13,'Medium',C.white);}
});
figma.viewport.scrollAndZoomIntoView(screens);
return {createdNodeIds:ids,mutatedNodeIds:[page.id],screens:screens.map(f=>({id:f.id,name:f.name,width:f.width,height:f.height})),totalScreens:screens.length};
